function toggleBrainWakeMode(){if(wakeModeActive)return stopBrainWakeMode();const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){if(window.AndroidVoice){voiceMode='capture';openVoice();toast('Say “Brain” followed by your task. Continuous wake mode needs the native upgrade.')}else toast('Wake mode needs Chrome microphone support.');return}wakeModeActive=true;$('#brainWakeToggle').classList.add('active');$('#brainWakeToggle').textContent='● Listening for “Brain”';wakeRecognition=new SR();wakeRecognition.lang='en-IN';wakeRecognition.continuous=true;wakeRecognition.interimResults=false;wakeRecognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){if(!e.results[i].isFinal)continue;let speech=e.results[i][0].transcript.trim(),lower=speech.toLowerCase(),at=lower.indexOf('brain');if(at>=0){let after=speech.slice(at+5).trim();if(after){voiceMode='capture';voiceSaved=false;$('#voiceOverlay').classList.add('open');$('#voiceTranscript').textContent=after;showVoiceResult(after);wakeArmed=false}else{wakeArmed=true;toast('Listening—tell Brain what to add.')}}else if(wakeArmed){voiceMode='capture';voiceSaved=false;$('#voiceOverlay').classList.add('open');showVoiceResult(speech);wakeArmed=false}}};wakeRecognition.onerror=e=>{if(e.error==='not-allowed'){stopBrainWakeMode();toast('Allow microphone access to use Brain wake mode.')}};wakeRecognition.onend=()=>{if(wakeModeActive)setTimeout(()=>{try{wakeRecognition.start()}catch{}},350)};try{wakeRecognition.start();toast('Brain wake mode is listening while this app stays open.')}catch{stopBrainWakeMode()}}
