function monthFeedItems(){let combined=[...tasks.map(t=>{let cat=taskCategory(t),kind=cat==='Follow-up'?'followup':cat.toLowerCase();return{title:t.title,time:t.time||currentTimeText(),date:taskDateISO(t),taskId:t.id,pendingSince:t.pendingSince||'',kind,category:cat,meta:[t.client,t.service,cat,t.done?'Completed':'Pending'].filter(Boolean).join(' · '),done:t.done}}),...meetings.map(m=>({title:m.title,time:m.time||currentTimeText(),date:meetingDateISO(m),kind:'meeting',category:'Meeting',meta:m.client||m.sub||'Meeting',done:false}))];let seen=new Set();return combined.filter(x=>{let key=x.date+'|'+x.title.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
