 let selectedDate=localISO(dates[selectedCalIndex]),tom=new Date();tom.setDate(tom.getDate()+1),label=selectedDate===localISO()?'Today':selectedDate===localISO(tom)?'Tomorrow':dates[selectedCalIndex].toLocaleDateString('en-IN',{weekday:'long'}),all=allCalendarItems(),list=all.filter(x=>taskDateISO(x)===selectedDate);
