 $$('[data-calendar-index]').forEach(e=>e.onclick=()=>openTaskActions(+e.dataset.calendarIndex));$$('[data-calendar-check]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleTaskEverywhere(b.dataset.calendarCheck)});
